#include <Arduino.h>

void setup() {
  pinMode(A0, INPUT);
  for (int pin = 2; pin <= 11; ++pin) {
    pinMode(pin, OUTPUT);
    digitalWrite(pin, LOW);
  }
}

void loop() {
  int raw = analogRead(A0);
  int count = (int)map(raw, 1023, 0, 0, 10);
  for (int segment = 1; segment <= 10; ++segment) {
    digitalWrite(segment + 1, segment <= count ? HIGH : LOW);
  }
  delay(10);
}
